    raw = gzip.decompress(base64.b85decode(payload))
    if hashlib.sha256(raw).hexdigest() != '0bde7bb506ce87b1a66f35001fd7e1ed08a81a6145ceb4f0f1be7944f81361fd':
        raise ValueError('Cell37 source fixture changed; no silent replacement.')
    fixture = json.loads(raw)
    count, errors = Counter(), Counter()

    def check(ok, message):
        if not bool(ok):
            raise AssertionError(message)

    def close(a, b, label, tol=3e-12):
        error = float(np.max(np.abs(np.asarray(a)-np.asarray(b))))
        errors[label] = max(errors[label], error)
        check(error < tol, f'{label}: {error}')

    def rat(x):
        q = Fraction(x)
        return str(q.numerator) if q.denominator == 1 else f'{q.numerator}/{q.denominator}'

    class NativeState:
        """Exact bitset implementation of the selected H=m=0 counting law."""
        def __init__(self, item):
            check((item['Gamma'],item['m'],item['H'])==(3,0,0), 'Fixture law changed')
            self.parents = [None if p is None else tuple(p) for p in item['parents']]
            self.F,self.P,self.tau,self.step = (int(item[k]) for k in ('F','P','tau','step'))
            self.chains=[];self.ancestry=[];self.recorded=set();self.pairs={}
            for z, pair in enumerate(self.parents):
                if z<2:
                    check(pair is None,'Only two primitive roots')
                    self.chains.append(1);self.ancestry.append(1<<z)
                else:
                    check(pair is not None and 0<=pair[0]<pair[1]<z and pair not in self.pairs,'Invalid native DAG')
                    a,b=pair
                    self.chains.append(self.chains[a]+self.chains[b])
                    self.ancestry.append(self.ancestry[a]|self.ancestry[b]|(1<<z))
                    self.pairs[pair]=z;self.recorded.update(pair)
            check(len(self.parents)==item['n'],'Fixture size')

        @staticmethod
        def members(bits):
            while bits:
                least=bits&-bits
                yield least.bit_length()-1
                bits-=least

        def evaluate(self, served):
            n=len(self.parents);q=min(3,n+self.F)
            W=tuple(sorted(served));check(len(set(W))==len(W) and all(0<=z<n for z in W),'Illegal maintenance set')
            forced=q-len(W)
            check(0<=forced<=self.F,'Illegal forced count')
            new_pairs=tuple(p for p in combinations(W,2) if p not in self.pairs)
            hits=Counter()
            for a,b in new_pairs:
                hits.update(self.members(self.ancestry[a]|self.ancestry[b]))
            repeat=sum(2*(2*self.chains[z]-2)*multiplicity for z,multiplicity in hits.items())
            first=sum(9*(2*self.chains[z]-2) for z in hits if z not in self.recorded)
            probability=Fraction(comb(self.F,forced),comb(n+self.F,q))
            return dict(served=W,forced_served=forced,new_pairs=new_pairs,repeat_part=repeat,
                first_use_premium=first,cost=repeat+first,first_written=tuple(sorted(z for z in hits if z not in self.recorded)),
                probability=probability,draw_multiplicity=comb(self.F,forced),
                next_n=n+len(new_pairs),next_F=self.F-forced+repeat+first,
                next_P=self.P+2*forced,next_tau=self.tau+len(W),next_step=self.step+1)

        def commit(self, served):
            row=self.evaluate(served);old_n=len(self.parents)
            newborn=[]
            for a,b in row['new_pairs']:
                z=len(self.parents)
                self.parents.append((a,b));self.chains.append(self.chains[a]+self.chains[b])
                self.ancestry.append(self.ancestry[a]|self.ancestry[b]|(1<<z))
                self.recorded.update((a,b));self.pairs[a,b]=z;newborn.append((z,a,b))
            for a,b in row['new_pairs']:
                check(a<old_n and b<old_n,'Newborn used in own burst')
            self.F,self.P,self.tau,self.step=(row[k] for k in ('next_F','next_P','next_tau','next_step'))
            row['newborns']=tuple(newborn)
            return row

    # Exact one-step native event domain: no duplicate logical-label copies count as
    # independent events. Logical states are not arguments of the native kernel.
    early=NativeState(fixture['worlds']['early'])
    total_weight=0;native_rows=[];expected_cost=Fraction(0)
    for size in range(4):
        for W in combinations(range(len(early.parents)),size):
            row=early.evaluate(W);total_weight+=row['draw_multiplicity']
            expected_cost+=row['probability']*row['cost']
            native_rows.append(row)
            count['exact_native_subsets']+=1
    check(total_weight==comb(early.F+len(early.parents),3),'Complete service law normalization')
    check(len(native_rows)==1160,'Frozen 19-object first-step inventory')

    # The original two qutrit factors are bound to the genesis siblings 3 and 4.
    # They remain separate from the four placement paths supplying storage noise.
    rr=np.arange(3);I3=np.eye(3,dtype=complex);I9=np.eye(9,dtype=complex)
    F3=np.exp(2j*np.pi*rr[:,None]*rr[None,:]/3)/sqrt(3)
    embed=np.eye(9,dtype=complex)[:,[0,4,8]]
    words=embed@F3;PC=embed@embed.conj().T
    close(words.conj().T@words,I3,'code_orthonormality')
    outcomes=tuple(product(range(3),repeat=2))
    vectors=[]
    for a,b in outcomes:
        vectors.append(np.kron(np.exp(-2j*np.pi*rr*a/3),np.exp(+2j*np.pi*rr*b/3))/3)
    vectors=np.array(vectors).T
    close(vectors@vectors.conj().T,I9,'local_readout_basis')
    fine=[np.outer(v,v.conj()) for v in vectors.T]
    grouped=[sum((fine[j] for j,(a,b) in enumerate(outcomes) if (b-a)%3==k),np.zeros((9,9),complex)) for k in range(3)]
    close(sum(grouped),I9,'target_POVM_completeness')

    # Independent cyclic construction of target Pi_k, exactly rank-three as an
    # operator-Schmidt expansion: the three X powers are trace-orthogonal.
    X=np.roll(I3,1,axis=0);powers=[np.linalg.matrix_power(X,m) for m in range(3)]
    gram=np.array([[np.trace(a.conj().T@b) for b in powers] for a in powers])
    close(gram,3*I3,'exact_trace_orthogonal_shift_powers')
    cyclic=[]
    for k in range(3):
        p=sum((np.exp(2j*np.pi*k*m/3)*np.kron(powers[m],powers[m]) for m in range(3)),np.zeros((9,9),complex))/3
        close(p,grouped[k],'cyclic_target_projector');cyclic.append(p)
        close(p@p,p,'target_projector_idempotence')
    # Exact integer orthogonality certificate rather than floating-rank selection.
    exact_gram=[[3 if a==b else 0 for b in range(3)] for a in range(3)]
    for a,b in product(range(3),repeat=2):
        perm_a=[(j+a)%3 for j in range(3)];perm_b=[(j+b)%3 for j in range(3)]
        check(sum(x==y for x,y in zip(perm_a,perm_b))==exact_gram[a][b],'Permutation trace certificate')
    count['exact_shift_trace_certificates']=9

    def partial_transpose(rho):
        return rho.reshape(3,3,3,3).transpose(0,3,2,1).reshape(9,9)
    def negativity(rho):
        ev=np.linalg.eigvalsh(partial_transpose(rho))
        return float(-ev[ev<0].sum())
    def td(a,b):
        return float(np.abs(np.linalg.eigvalsh(a-b)).sum()/2)

    # Same-carrier obstruction witness. |00> is a product input INSIDE the code.
    # A product-Kraus branch cannot send it to the entangled target Omega_k.
    product_input=embed[:,0];product_rho=np.outer(product_input,product_input.conj())
    witness=[]
    for k,p in enumerate(grouped):
        branch=p@product_rho@p
        prob=float(np.trace(branch).real);post=branch/prob
        close(prob,1/3,'witness_branch_probability')
        close(post,np.outer(words[:,k],words[:,k].conj()),'product_to_entangled_target_witness')
        close(negativity(post),1,'witness_negativity')
        witness.append(dict(label=k,probability=prob,negativity=negativity(post)))
    # Native raw first-write trit is independent of logical word. A fake g=k map
    # has the same uniform marginals but a DIFFERENT joint law.
    raw_joint=[[Fraction(1,9) for g in range(3)] for k in range(3)]
    forged_joint=[[Fraction(int(g==k),3) for g in range(3)] for k in range(3)]
    raw_tv=sum(abs(raw_joint[k][g]-forged_joint[k][g]) for k,g in outcomes)/2
    check(raw_tv==Fraction(2,3),'Uniform marginals are insufficient')

    # Secondary logical renewal: ideal local readout, independent fresh Omega0
    # source, feed-forward D(k/3), NEW output factors. No controlled quantum gate.
    renewal=[]
    for j,(a,b) in enumerate(outcomes):
        k=(b-a)%3
        K=np.outer(words[:,k],vectors[:,j].conj())
        renewal.append(K)
        close(K@embed,(words[:,k,None]@words[:,k,None].conj().T@embed)/sqrt(3),'fine_branch_on_code')
    close(sum(K.conj().T@K for K in renewal),I9,'renewal_trace_preserving')
    for k in range(3):
        close(sum((K.conj().T@K for K,(a,b) in zip(renewal,outcomes) if (b-a)%3==k),np.zeros((9,9),complex)),grouped[k],'same_full_outcome_POVM')

    def target_branch(rho,k):
        return grouped[k]@rho@grouped[k]
    def renewal_branch(rho,k):
        return sum((K@rho@K.conj().T for K,(a,b) in zip(renewal,outcomes) if (b-a)%3==k),np.zeros((9,9),complex))
    for i,j in product(range(3),repeat=2):
        unit=np.outer(embed[:,i],embed[:,j])
        for k in range(3):
            close(target_branch(unit,k),renewal_branch(unit,k),'all_code_matrix_units')
