            row=st.commit((*anchors,src))
            new_anchors=tuple(st.pairs[tuple(sorted((src,a)))] for a in anchors)
            extra=tuple(z for z,a,b in row['newborns'] if z not in new_anchors)
            check(all(z>=n for z in new_anchors),'Fresh factors are not fresh')
            check(row['cost']==row['repeat_part']+row['first_use_premium'],'Charge decomposition')
            check(row['forced_served']==0 and st.F==before['F']+row['cost'],'Do not treat incurred work as discharged')
            check(st.tau-before['tau']==3 and st.P==before['P'],'Native ledger bookkeeping')
